
  /* LinguaFlash Pro: embedded Chinese Daily Podcast pack (40 curated lessons; 20 supplementary HSK4–HSK5 lessons). */
  const LFYT_STANDALONE_V7_B64 = '';
  let lfYoutubeFrameLoaded = false;

  function lfDecodeUtf8Base64(b64) {
    const raw = atob(b64);
    const bytes = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
    return new TextDecoder('utf-8').decode(bytes);
  }

  function syncLfYoutubeLanguage(lang) {
    const targetLang = ['vi','en','zh'].includes(lang) ? lang : ((typeof currentUiLang==='string' && currentUiLang) ? currentUiLang : 'vi');
    const frame = document.getElementById('lfYoutubeFrame');
    if (!frame || !frame.contentWindow) return;
    try {
      if (typeof frame.contentWindow.setLfytUiLanguage === 'function') {
        frame.contentWindow.setLfytUiLanguage(targetLang);
      } else {
        frame.contentWindow.postMessage({type:'lfyt-lang', lang:targetLang}, '*');
      }
    } catch (e) {
      try { frame.contentWindow.postMessage({type:'lfyt-lang', lang:targetLang}, '*'); } catch (_) {}
    }
  }

  function initLfYoutubeFrame() {
    const frame = document.getElementById('lfYoutubeFrame');
    if (!frame || lfYoutubeFrameLoaded) return;
    try {
      let moduleHtml = lfDecodeUtf8Base64(LFYT_STANDALONE_V7_B64);
      const hostMeta = '<meta name="lfyt-host-protocol" content="' + String(window.location.protocol || '') + '">';
      moduleHtml = moduleHtml.replace('<head>', '<head>' + hostMeta);
      frame.onload = () => setTimeout(() => syncLfYoutubeLanguage(), 30);
      frame.srcdoc = moduleHtml;
      lfYoutubeFrameLoaded = true;
      setTimeout(() => syncLfYoutubeLanguage(), 120);
    } catch (err) {
      console.error('YouTube Podcast module:', err);
      frame.style.height = '320px';
      frame.srcdoc = '<!doctype html><meta charset="utf-8"><body style="font-family:system-ui;padding:24px"><h2>Không thể mở module YouTube Podcast</h2><p>Vui lòng tải lại trang.</p></body>';
    }
  }

  function lfYoutubeSpeak(text, rate=.86) {
    if (!('speechSynthesis' in window) || !text) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(String(text));
    u.lang = 'zh-CN'; u.rate = Number(rate) || .86; u.pitch = 1;
    window.speechSynthesis.speak(u);
  }

  function lfYoutubeRepeat(text, rate=.78, count=3) {
    if (!('speechSynthesis' in window) || !text) return;
    window.speechSynthesis.cancel();
    let n = 0; const total = Math.max(1, Math.min(Number(count)||3, 5));
    const run = () => {
      if (n >= total) return; n++;
      const u = new SpeechSynthesisUtterance(String(text));
      u.lang = 'zh-CN'; u.rate = Number(rate) || .78; u.pitch = 1;
      u.onend = () => setTimeout(run, 450);
      window.speechSynthesis.speak(u);
    };
    run();
  }

  async function lfYoutubeCopy(text) {
    const value = String(text || '');
    try {
      if (navigator.clipboard && window.isSecureContext) { await navigator.clipboard.writeText(value); return; }
    } catch (e) {}
    const ta = document.createElement('textarea');
    ta.value = value; ta.setAttribute('readonly',''); ta.style.position='fixed'; ta.style.opacity='0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    ta.remove();
  }

  function lfYoutubeScrollToVideo() {
    const frame = document.getElementById('lfYoutubeFrame');
    if (frame) frame.scrollIntoView({behavior:'smooth', block:'start'});
  }

  // Explicit exports let the same-origin srcdoc iframe call these synchronously from a real click.
  // This keeps browser user-activation for speech/clipboard, unlike an asynchronous postMessage hop.
  window.lfYoutubeSpeak = lfYoutubeSpeak;
  window.lfYoutubeRepeat = lfYoutubeRepeat;
  window.lfYoutubeCopy = lfYoutubeCopy;
  window.lfYoutubeScrollToVideo = lfYoutubeScrollToVideo;

  window.addEventListener('message', function(event) {
    const frame = document.getElementById('lfYoutubeFrame');
    if (!frame || event.source !== frame.contentWindow || !event.data) return;
    if (event.data.type === 'lfyt-height') {
      const h = Number(event.data.height);
      if (Number.isFinite(h) && h > 300) frame.style.height = Math.min(Math.max(h + 8, 620), 20000) + 'px';
    } else if (event.data.type === 'lfyt-speak') {
      lfYoutubeSpeak(event.data.text, event.data.rate);
    } else if (event.data.type === 'lfyt-repeat') {
      lfYoutubeRepeat(event.data.text, event.data.rate, event.data.count);
    } else if (event.data.type === 'lfyt-copy') {
      lfYoutubeCopy(event.data.text);
    } else if (event.data.type === 'lfyt-scroll-video') {
      lfYoutubeScrollToVideo();
    }
  });
